def api_fetch(method, url, params=None, body=None, id_map=None):
    """Fetch from the world API with explicit method/url/params/body (Google Sheets style).
    id_map: dict mapping placeholder tokens in url (e.g. {spreadsheetId}) to values."""
    params = params or {}
    if id_map:
        for k, v in id_map.items():
            url = url.replace("{" + k + "}", str(v))
    return tools.mcp__world__api_fetch(method=method, url=url, params=params, body=body or {})

